sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (newValue === 'incident') {
        // Popup only when the user changes the value, not on form load
        if (!isLoading) {
            alert('Incidents are not raised here. Please use the Incident module to log an incident.');
        }
        g_form.clearValue('subcategory');
        g_form.setMandatory('subcategory', false);
        g_form.setVisible('subcategory', false);
        return;
    }
    // Any other category: show Subcategory, mandatory once a category is chosen
    g_form.setVisible('subcategory', true);
    g_form.setMandatory('subcategory', newValue !== '');
}
